62	  const rules = validateIntelRules(options.rules ?? defaultIntelRules);
63	  if (!rules.ok) throw new RangeError(`invalid intel rules: ${rules.issues.join("; ")}`);
64	  const map = options.map ?? seaMap;
65	  const start = options.controlStartTick ?? 0;
66	  requireInteger(start, "controlStartTick");
67	  if (start < 0) throw new RangeError(`controlStartTick must not be negative, got ${start}`);
68	  for (const [value, name] of [
69	    [map.widthTiles, "widthTiles"],
70	    [map.heightTiles, "heightTiles"],
71	    [map.subUnitsPerTile, "subUnitsPerTile"],
72	  ] as const) {
73	    requireInteger(value, name);
74	    if (value <= 0) throw new RangeError(`${name} must be positive, got ${value}`);
75	  }
76	  if (map.widthTiles < rules.value.sectorColumns || map.heightTiles < rules.value.sectorRows) {
77	    throw new RangeError(`a ${map.widthTiles} × ${map.heightTiles} map cannot hold ${rules.value.sectorColumns} × ${rules.value.sectorRows} sectors`);
78	  }
79	  requireInteger(options.finalIsland.x, "finalIsland.x");
80	  requireInteger(options.finalIsland.y, "finalIsland.y");
81	  return {
82	    types: presetRubbingTypes(rulesPresets[options.preset]),
83	    widthTiles: map.widthTiles,
84	    heightTiles: map.heightTiles,
85	    subUnitsPerTile: map.subUnitsPerTile,
86	    sectorColumns: rules.value.sectorColumns,
87	    sectorRows: rules.value.sectorRows,
88	    sectorNames: [...rules.value.sectorNames],
89	    islandNames: map.islands.map((island) => island.name),
90	    controlStartTick: start,
91	    finalIsland: { x: options.finalIsland.x, y: options.finalIsland.y },
92	    carrierIntervalTicks: rules.value.carrierIntervalTicks,
93	    sectorRevealTick: start + rules.value.sectorRevealTicks,
94	    carrierRevealTick: start + rules.value.carrierRevealTicks,
95	  };
96	}
