102	export function sectorOfTile(config: IntelConfig, tileX: number, tileY: number): number {
103	  const x = Math.min(Math.max(tileX, 0), config.widthTiles - 1);
104	  const y = Math.min(Math.max(tileY, 0), config.heightTiles - 1);
105	  const column = Math.floor((x * config.sectorColumns) / config.widthTiles);
106	  const row = Math.floor((y * config.sectorRows) / config.heightTiles);
107	  return row * config.sectorColumns + column;
108	}
